VALUES ('aa36c0a4-d7ee-505c-ba34-e7de56ea4940'::uuid, 'b284bcf3-bb98-5dd4-84d3-2211c254b43c'::uuid, 'slide'::public.content_type, 'Engage: What Is Inside the Workflow?', 'Enter the workplace mission, learner role, pressure, authority boundary and required module outcome. The Workflow Owner cannot review the case efficiently because the supplied request, instruction, sources, output, status, observation and owner objects are not yet organised into a clear workflow structure. The learner must identify each object type, map its place and show confirmed, unconfirmed and review-layer relationships without inventing source use.', 'https://bucket.lte.rareminds.in/resources/capabilities/ITS-CAP-037/levels/CAP037_L1/modules-1/content/CAP037_L1_M1_D1_Engage.pptx', 1, 360, NULL, 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 127917, 1, 'published'::public.content_publish_status)
